'use strict';

function assembleReaderProfile(readerId, readers, loans) {
  if (typeof readerId !== 'string' || readerId.trim() === '') {
    throw new TypeError('readerId must be a non-empty string');
  }
  if (!Array.isArray(readers) || !Array.isArray(loans)) {
    throw new TypeError('readers and loans must be arrays');
  }

  let selected = null;
  for (const reader of readers) {
    if (reader === null || typeof reader !== 'object' ||
        typeof reader.id !== 'string' || reader.id.trim() === '' ||
        typeof reader.displayName !== 'string' || reader.displayName.trim() === '') {
      throw new TypeError('malformed reader');
    }
    if (selected === null && reader.id.trim() === readerId.trim()) {
      selected = { id: reader.id.trim(), displayName: reader.displayName.trim() };
    }
  }

  const activeTitles = [];
  for (const loan of loans) {
    if (loan === null || typeof loan !== 'object' ||
        typeof loan.readerId !== 'string' || loan.readerId.trim() === '' ||
        typeof loan.title !== 'string' || loan.title.trim() === '' ||
        typeof loan.returned !== 'boolean') {
      throw new TypeError('malformed loan');
    }
    if (selected !== null && loan.readerId.trim() === selected.id && !loan.returned) {
      activeTitles.push(loan.title.trim());
    }
  }

  return selected === null ? null : {
    id: selected.id,
    displayName: selected.displayName,
    activeTitles
  };
}

module.exports = { assembleReaderProfile };
